-- Initial CLAIMED.WORLD schema. No player data or credentials.
CREATE SCHEMA IF NOT EXISTS game;
REVOKE ALL ON SCHEMA game FROM PUBLIC, anon, authenticated;
SET search_path TO game, public;
CREATE TABLE users (
      id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE,
      password TEXT NOT NULL, color TEXT NOT NULL, created_at BIGINT NOT NULL,
      wallet BIGINT NOT NULL DEFAULT 100 CHECK(wallet >= 0), collected_slots BIGINT NOT NULL DEFAULT 0,
      generation_anchor BIGINT NOT NULL, alliance_id TEXT, cooldown_until BIGINT NOT NULL DEFAULT 0,
      banned BIGINT NOT NULL DEFAULT 0, demo BIGINT NOT NULL DEFAULT 0, alliance_role TEXT NOT NULL DEFAULT 'member'
    , is_admin BIGINT NOT NULL DEFAULT 0, alliance_joined_at BIGINT NOT NULL DEFAULT 0, capacity_bonus BIGINT NOT NULL DEFAULT 0, rate_bonus BIGINT NOT NULL DEFAULT 0, reward_season BIGINT NOT NULL DEFAULT 0);
ALTER TABLE game.users ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.users FROM anon, authenticated;
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
ALTER TABLE game.sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sessions FROM anon, authenticated;
CREATE TABLE seasons (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, starts_at BIGINT NOT NULL, ends_at BIGINT NOT NULL, archived_at BIGINT, snapshot TEXT, processed_at BIGINT NOT NULL DEFAULT 0);
ALTER TABLE game.seasons ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.seasons FROM anon, authenticated;
CREATE TABLE alliances (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, color TEXT NOT NULL, emblem TEXT NOT NULL, description TEXT NOT NULL, leader_id TEXT NOT NULL REFERENCES users(id), invite TEXT UNIQUE NOT NULL, created_at BIGINT NOT NULL, active BIGINT NOT NULL DEFAULT 1, treasury BIGINT NOT NULL DEFAULT 0 CHECK(treasury >= 0), objective TEXT NOT NULL DEFAULT '', target_ids TEXT NOT NULL DEFAULT '[]');
ALTER TABLE game.alliances ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.alliances FROM anon, authenticated;
CREATE TABLE contributions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), camp_id TEXT NOT NULL, country_id TEXT NOT NULL, amount BIGINT NOT NULL CHECK(amount > 0), created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, season_id BIGINT NOT NULL REFERENCES seasons(id));
ALTER TABLE game.contributions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.contributions FROM anon, authenticated;
CREATE TABLE ownership (country_id TEXT NOT NULL, season_id BIGINT NOT NULL, camp_id TEXT, changes BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(country_id, season_id));
ALTER TABLE game.ownership ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.ownership FROM anon, authenticated;
CREATE TABLE activity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY , text TEXT NOT NULL, color TEXT NOT NULL, created_at BIGINT NOT NULL, country_id TEXT, season_id BIGINT NOT NULL);
ALTER TABLE game.activity ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.activity FROM anon, authenticated;
CREATE TABLE webhook_events (id TEXT PRIMARY KEY, created_at BIGINT NOT NULL);
ALTER TABLE game.webhook_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.webhook_events FROM anon, authenticated;
CREATE TABLE reports (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), target TEXT NOT NULL, reason TEXT NOT NULL, created_at BIGINT NOT NULL, resolved BIGINT NOT NULL DEFAULT 0);
ALTER TABLE game.reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.reports FROM anon, authenticated;
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count BIGINT NOT NULL, resets_at BIGINT NOT NULL);
ALTER TABLE game.rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.rate_limits FROM anon, authenticated;
CREATE TABLE uploads (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL);
ALTER TABLE game.uploads ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.uploads FROM anon, authenticated;
CREATE TABLE sponsors (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), country_id TEXT NOT NULL, season_id BIGINT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, url TEXT NOT NULL, initials TEXT NOT NULL, color TEXT NOT NULL, amount BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', payment_status TEXT NOT NULL DEFAULT 'unpaid', checkout_id TEXT, checkout_expires BIGINT, created_at BIGINT NOT NULL, logo_id TEXT REFERENCES uploads(id));
ALTER TABLE game.sponsors ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsors FROM anon, authenticated;
CREATE TABLE schema_migrations (id TEXT PRIMARY KEY, applied_at BIGINT NOT NULL);
ALTER TABLE game.schema_migrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.schema_migrations FROM anon, authenticated;
CREATE TABLE alliance_memberships (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, alliance_id TEXT NOT NULL REFERENCES alliances(id) ON DELETE CASCADE, joined_at BIGINT NOT NULL, left_at BIGINT);
ALTER TABLE game.alliance_memberships ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.alliance_memberships FROM anon, authenticated;
CREATE TABLE alliance_ledger (id TEXT PRIMARY KEY, alliance_id TEXT NOT NULL REFERENCES alliances(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, season_id BIGINT NOT NULL, kind TEXT NOT NULL, amount BIGINT NOT NULL CHECK(amount >= 0), country_id TEXT, created_at BIGINT NOT NULL);
ALTER TABLE game.alliance_ledger ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.alliance_ledger FROM anon, authenticated;
CREATE TABLE treasury_lots (id TEXT PRIMARY KEY, alliance_id TEXT NOT NULL REFERENCES alliances(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, season_id BIGINT NOT NULL, amount BIGINT NOT NULL, remaining BIGINT NOT NULL CHECK(remaining >= 0), created_at BIGINT NOT NULL);
ALTER TABLE game.treasury_lots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.treasury_lots FROM anon, authenticated;
CREATE TABLE contribution_funding (contribution_id TEXT NOT NULL REFERENCES contributions(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount BIGINT NOT NULL CHECK(amount > 0), PRIMARY KEY(contribution_id,user_id));
ALTER TABLE game.contribution_funding ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.contribution_funding FROM anon, authenticated;
CREATE TABLE ownership_periods (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, country_id TEXT NOT NULL, season_id BIGINT NOT NULL, camp_id TEXT NOT NULL, starts_at BIGINT NOT NULL, ends_at BIGINT);
ALTER TABLE game.ownership_periods ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.ownership_periods FROM anon, authenticated;
CREATE TABLE season_rewards (season_id BIGINT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_season BIGINT NOT NULL, capacity_bonus BIGINT NOT NULL, rate_bonus BIGINT NOT NULL, starting_influence BIGINT NOT NULL, metrics TEXT NOT NULL, PRIMARY KEY(season_id,user_id));
ALTER TABLE game.season_rewards ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.season_rewards FROM anon, authenticated;
CREATE TABLE sponsor_wallets (user_id TEXT PRIMARY KEY REFERENCES users(id), balance_cents BIGINT NOT NULL DEFAULT 0 CHECK(balance_cents>=0), debt_cents BIGINT NOT NULL DEFAULT 0 CHECK(debt_cents>=0), frozen BIGINT NOT NULL DEFAULT 0);
ALTER TABLE game.sponsor_wallets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsor_wallets FROM anon, authenticated;
CREATE TABLE sponsor_topups (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), request_id TEXT NOT NULL, amount_cents BIGINT NOT NULL CHECK(amount_cents>=500), status TEXT NOT NULL DEFAULT 'pending', checkout_id TEXT UNIQUE, payment_intent TEXT UNIQUE, checkout_expires BIGINT, credited_at BIGINT, refunded_cents BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, UNIQUE(user_id,request_id));
ALTER TABLE game.sponsor_topups ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsor_topups FROM anon, authenticated;
CREATE TABLE sponsor_stakes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), campaign_id TEXT NOT NULL REFERENCES sponsors(id), country_id TEXT NOT NULL, amount_cents BIGINT NOT NULL CHECK(amount_cents>=0), placed_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, changed_at BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'active', origin_id TEXT NOT NULL);
ALTER TABLE game.sponsor_stakes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsor_stakes FROM anon, authenticated;
CREATE TABLE sponsor_ownership (country_id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL, changed_at BIGINT NOT NULL);
ALTER TABLE game.sponsor_ownership ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsor_ownership FROM anon, authenticated;
CREATE TABLE sponsor_clock (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK(id=1), processed_at BIGINT NOT NULL);
ALTER TABLE game.sponsor_clock ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsor_clock FROM anon, authenticated;
CREATE TABLE sponsor_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, amount_cents BIGINT NOT NULL, wallet_delta BIGINT NOT NULL DEFAULT 0, from_country TEXT, to_country TEXT, stake_id TEXT, topup_id TEXT, created_at BIGINT NOT NULL);
ALTER TABLE game.sponsor_ledger ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsor_ledger FROM anon, authenticated;
CREATE TABLE sponsor_disputes (payment_intent TEXT PRIMARY KEY, event_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at BIGINT NOT NULL);
ALTER TABLE game.sponsor_disputes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.sponsor_disputes FROM anon, authenticated;
CREATE TABLE progression_unlocks (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,id TEXT NOT NULL,unlocked_at BIGINT NOT NULL,PRIMARY KEY(user_id,id));
ALTER TABLE game.progression_unlocks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.progression_unlocks FROM anon, authenticated;
CREATE TABLE player_progress (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,frame TEXT NOT NULL DEFAULT 'frame-none',title TEXT NOT NULL DEFAULT 'title-none',border TEXT NOT NULL DEFAULT 'border-solid',tutorial_step BIGINT NOT NULL DEFAULT 0,tutorial_dismissed BIGINT NOT NULL DEFAULT 0);
ALTER TABLE game.player_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.player_progress FROM anon, authenticated;
CREATE TABLE player_objectives (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,objective_id TEXT NOT NULL,season_id BIGINT NOT NULL REFERENCES seasons(id),started_at BIGINT NOT NULL);
ALTER TABLE game.player_objectives ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.player_objectives FROM anon, authenticated;
CREATE TABLE battle_orders (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,source_id TEXT NOT NULL,destination_id TEXT NOT NULL,target_camp TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),mode TEXT NOT NULL,destroyed BIGINT NOT NULL,survivors BIGINT NOT NULL,created_at BIGINT NOT NULL,season_id BIGINT NOT NULL REFERENCES seasons(id),UNIQUE(user_id,request_id));
ALTER TABLE game.battle_orders ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.battle_orders FROM anon, authenticated;
CREATE TABLE influence_burns (id TEXT PRIMARY KEY,contribution_id TEXT NOT NULL REFERENCES contributions(id) ON DELETE CASCADE,attack_id TEXT NOT NULL REFERENCES battle_orders(id),amount BIGINT NOT NULL CHECK(amount>0),created_at BIGINT NOT NULL);
ALTER TABLE game.influence_burns ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.influence_burns FROM anon, authenticated;
CREATE TABLE influence_transfers (contribution_id TEXT PRIMARY KEY REFERENCES contributions(id) ON DELETE CASCADE,source_id TEXT NOT NULL REFERENCES contributions(id),attack_id TEXT NOT NULL REFERENCES battle_orders(id));
ALTER TABLE game.influence_transfers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON game.influence_transfers FROM anon, authenticated;
CREATE INDEX contribution_active ON contributions(season_id, country_id, expires_at);
CREATE INDEX ownership_period_season ON ownership_periods(season_id,country_id);
CREATE UNIQUE INDEX ownership_period_open ON ownership_periods(season_id,country_id) WHERE ends_at IS NULL;
CREATE INDEX treasury_lot_pending ON treasury_lots(alliance_id,season_id,created_at) WHERE remaining>0;
CREATE INDEX treasury_log_recent ON alliance_ledger(alliance_id,season_id,created_at);
CREATE INDEX sponsor_stakes_active ON sponsor_stakes(country_id,expires_at) WHERE status='active';
CREATE INDEX sponsor_stakes_user ON sponsor_stakes(user_id,status,expires_at);
CREATE INDEX influence_burn_lookup ON influence_burns(contribution_id,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS users_username_ci ON game.users (lower(username));
CREATE UNIQUE INDEX IF NOT EXISTS alliances_name_ci ON game.alliances (lower(name));
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('sponsor-logos','sponsor-logos',false,1048576,ARRAY['image/webp']) ON CONFLICT(id) DO NOTHING;
RESET search_path;
